effect.shader:
// globais do Node ligados ao motor (tools/nodevideo/ligar_globais.py)
#define _resolution acTamanhoDaTela
vec4 u_xlat0;
vec4 u_xlat1;
bool u_xlatb1;
vec4 u_xlat2;
bvec2 u_xlatb2;
vec4 u_xlat3;
vec4 u_xlat4;
vec4 u_xlat5;
float u_xlat7;
vec2 u_xlat14;
bvec2 u_xlatb14;
vec2 u_xlat15;
float u_xlat19;
float u_xlat20;
void main()
{
    u_xlat0 = texture(inputImg, acScreenNorm.xy);
    u_xlat1.xyz = _color.xyz * vec3(0.305306017, 0.305306017, 0.305306017) + vec3(0.682171106, 0.682171106, 0.682171106);
    u_xlat1.xyz = _color.xyz * u_xlat1.xyz + vec3(0.0125228781, 0.0125228781, 0.0125228781);
    u_xlat1.xyz = u_xlat1.xyz * _color.xyz;
    u_xlat19 = acScreenNorm.x;
    u_xlat19 = u_xlat19 + -0.5;
    u_xlat2.x = _resolution.x / _resolution.y;
    u_xlat2.x = u_xlat19 * u_xlat2.x;
    u_xlat2.y = (-acScreenNorm.y) + 0.5;
    u_xlat2.xy = u_xlat2.xy + (-_position.xy);
    u_xlat2.xy = abs(u_xlat2.xy) / vec2(vec2(_spacing, _spacing));
    u_xlatb14.xy = greaterThanEqual(u_xlat2.xyxy, (-u_xlat2.xyxy)).xy;
    u_xlat2.xy = fract(abs(u_xlat2.xy));
    {
        vec4 hlslcc_movcTemp = u_xlat2;
        hlslcc_movcTemp.x = (u_xlatb14.x) ? u_xlat2.x : (-u_xlat2.x);
        hlslcc_movcTemp.y = (u_xlatb14.y) ? u_xlat2.y : (-u_xlat2.y);
        u_xlat2 = hlslcc_movcTemp;
    }
    u_xlat2.xy = u_xlat2.xy * vec2(vec2(_spacing, _spacing));
    u_xlat2.xy = u_xlat2.xy / vec2(vec2(_spacing, _spacing));
    u_xlat2.xy = u_xlat2.xy + vec2(-0.5, -0.5);
    u_xlat2.xy = -abs(u_xlat2.xy) * vec2(2.0, 2.0) + vec2(1.0, 1.0);
    u_xlat19 = _width / _spacing;
    u_xlat19 = clamp(u_xlat19, 0.0, 1.0);
    u_xlat14.x = u_xlat19 * _smoothing;
    u_xlat20 = u_xlat19 * 0.5;
    u_xlat20 = max(u_xlat20, u_xlat14.x);
    u_xlat3.xy = vec2(vec2(_width, _width)) + vec2(-0.0120000001, -0.00600000005);
    u_xlat3.xy = u_xlat3.xy * vec2(-499.999908, -999.999817);
    u_xlat3.xy = clamp(u_xlat3.xy, 0.0, 1.0);
    u_xlat15.xy = u_xlat3.xy * vec2(-2.0, -2.0) + vec2(3.0, 3.0);
    u_xlat3.xy = u_xlat3.xy * u_xlat3.xy;
    u_xlat3.xy = u_xlat3.xy * u_xlat15.xy;
    u_xlat20 = (-u_xlat19) * _smoothing + u_xlat20;
    u_xlat14.x = u_xlat3.x * u_xlat20 + u_xlat14.x;
    u_xlat20 = max(u_xlat19, u_xlat14.x);
    u_xlat20 = (-u_xlat14.x) + u_xlat20;
    u_xlat14.x = u_xlat3.y * u_xlat20 + u_xlat14.x;
    u_xlat19 = (-u_xlat19) + 1.0;
    u_xlat20 = (-u_xlat14.x) + u_xlat19;
    u_xlat19 = u_xlat14.x + u_xlat19;
    u_xlat19 = (-u_xlat20) + u_xlat19;
    u_xlat2.xy = (-vec2(u_xlat20)) + u_xlat2.xy;
    u_xlat19 = float(1.0) / u_xlat19;
    u_xlat2.xy = vec2(u_xlat19) * u_xlat2.xy;
    u_xlat2.xy = clamp(u_xlat2.xy, 0.0, 1.0);
    u_xlat14.xy = u_xlat2.xy * vec2(-2.0, -2.0) + vec2(3.0, 3.0);
    u_xlat2.xy = u_xlat2.xy * u_xlat2.xy;
    u_xlat2.xy = u_xlat2.xy * u_xlat14.xy;
    u_xlat19 = max(u_xlat2.y, u_xlat2.x);
    u_xlat2.xyz = vec3(u_xlat19) * u_xlat1.xyz;
    u_xlat2.w = u_xlat19 * _color.w;
    u_xlatb1 = int(_blend_mode)==1;
    u_xlat3 = u_xlat0 * u_xlat2;
    u_xlat7 = (-u_xlat2.w) * u_xlat0.w + 1.0;
    u_xlat4 = u_xlat0 * vec4(u_xlat7);
    u_xlat4 = u_xlat2 * u_xlat3.wwww + u_xlat4;
    u_xlat1 = (bool(u_xlatb1)) ? u_xlat3 : u_xlat4;
    u_xlat3.xyz = u_xlat2.xyz;
    u_xlat1 = (int(_blend_mode) != 0) ? u_xlat1 : u_xlat3;
    if(int(_use_inner_mask) != 0) {
        u_xlatb2.xy = equal(ivec4(int(_show_inner_mask), int(_b_clip_mask), int(_show_inner_mask), int(_show_inner_mask)), ivec4(1, 1, 0, 0)).xy;
        u_xlat3 = (u_xlatb2.x) ? vec4(1.0, 0.0, 1.0, 1.0) : u_xlat1;
        u_xlat4 = texture(Mask, acScreenNorm.xy);
        u_xlat5 = (-u_xlat4) + vec4(1.0, 1.0, 1.0, 1.0);
        u_xlat0 = u_xlat0 * u_xlat5;
        u_xlat0 = u_xlat3 * u_xlat4 + u_xlat0;
        u_xlat2.x = u_xlat4.x * u_xlat0.w;
        fragColor.w = (u_xlatb2.y) ? u_xlat2.x : u_xlat0.w;
        fragColor.xyz = u_xlat0.xyz;
    } else {
        fragColor = u_xlat1;
    }
    return;
}
